True def transform(grid):
    rows = []
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    if not rows:
        return []
    keep_cols = []
    for j in range(len(rows[0])):
        if not keep_cols or any(row[j] != row[keep_cols[-1]] for row in rows):
            keep_cols.append(j)
    return [[row[j] for j in keep_cols] for row in rows]
